async function createUserFromForm(){const fields=document.querySelectorAll('.user-form input,.user-form select');const [name,email,role,password]=[...fields].map(field=>field.value.trim());if(!name||!email||!role||!password||role==='Selecione o perfil'){toast('Preencha todos os campos do usuario');return;}const result=await supabaseClient.functions.invoke('admin-create-user',{body:{name,email,role,password}});if(result.error){toast('Nao foi possivel criar o usuario');return;}toast('Usuario criado com sucesso');render();}
async function saveSettings(){const inputs=[...document.querySelectorAll('.settings-form input,.settings-form select')];const settings=inputs.map((input,index)=>({key:`setting_${index}`,value:input.value,updated_by:authenticatedUser.id,updated_at:new Date().toISOString()}));const result=await supabaseClient.from('operational_settings').upsert(settings,{onConflict:'key'});if(result.error){toast('Nao foi possivel salvar configuracoes');return;}toast('Configuracoes salvas no servidor');}
function exportOperations(){const columns=['DT','DATA','TIPO','PLACA','CLIENTE','TRANSPORTADORA','MOTORISTA','STATUS','DOCA','TONELADAS'];const lines=[columns,...operations.map(item=>[item.dt,item.date,item.type,item.plate,item.client,item.carrier,item.driver,item.status,item.dock,item.tons||''].map(value=>`"${String(value??'').replace(/"/g,'""')}"`))].map(line=>line.join(';'));const blob=new Blob([`\ufeff${lines.join('\r\n')}`],{type:'text/csv;charset=utf-8'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=`torre-sul-${saoPauloNow().toISOString().slice(0,10)}.csv`;link.click();URL.revokeObjectURL(link.href);}
async function editPlate(event){const button=event.target.closest('[data-operation]');const dt=button?.dataset.operation;if(!dt)return;const operation=operations.find(item=>item.dt===dt);if(!operation)return;const plate=window.prompt('Informe a nova placa/cavalo:',operation.plate);if(!plate||plate===operation.plate)return;const result=await supabaseClient.from('operations').update({plate:plate.trim(),horse_plate:plate.trim(),updated_at:new Date().toISOString()}).eq('id',operation.id);if(result.error){toast('Nao foi possivel atualizar a placa');return;}await loadRemoteState();toast('Placa atualizada no servidor');}
document.addEventListener('click',event=>{const button=event.target.closest('button');if(!button)return;const text=button.textContent.trim();if(text==='CRIAR USUARIO'){event.preventDefault();event.stopImmediatePropagation();createUserFromForm();}else if(button.closest('.settings-actions')&&text.includes('SALVAR')){event.preventDefault();event.stopImmediatePropagation();saveSettings();}else if(text.includes('EXPORTAR RELATORIO')){event.preventDefault();event.stopImmediatePropagation();exportOperations();}else if(text==='EDITAR PLACA'){event.preventDefault();event.stopImmediatePropagation();editPlate(event);}},true);
