function escapeHtml(value){return String(value??'').replace(/[&<>'"]/g,character=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[character]));}
function persistState(){if(authenticatedUser)syncRemoteState();}
async function signIn(event){event.preventDefault();const error=document.querySelector('#auth-error');error.textContent='';const email=document.querySelector('#auth-email').value.trim();const password=document.querySelector('#auth-password').value;const result=await supabaseClient.auth.signInWithPassword({email,password});if(result.error){error.textContent='E-mail ou senha invalidos.';return;}authenticatedUser=result.data.user;document.querySelector('#auth-screen').hidden=true;await loadRemoteState();subscribeToRemoteState();}
