function fromRemoteOperation(row){return {id:row.id,dt:row.dt,date:new Date(`${row.operation_date}T00:00:00`).toLocaleDateString('pt-BR'),plate:row.plate,client:row.client,carrier:row.carrier,driver:row.driver,type:row.operation_type,dock:row.dock_number?`DOCA ${row.dock_number}`:'-',start:row.start_time?.slice(0,5)||'-',elapsed:row.elapsed,sla:row.sla,status:row.status,risk:row.risk,tone:row.tone,age:row.age,next:row.next_action,lastAction:row.last_action?.slice(0,5),tons:row.tons,uf:row.uf,loadType:row.load_type,historyProblem:row.history_problem,guideCall:row.guide_call,deliveryInfo:row.delivery_info,otmDate:row.otm_date,otmTime:row.otm_time,horsePlate:row.horse_plate,composition:row.composition,arrivalAt:row.arrival_at,cdEntryAt:row.cd_entry_at,dockAt:row.dock_at,operationStartedAt:row.operation_started_at,operationFinishedAt:row.operation_finished_at,exitedAt:row.exited_at};}
function applyReportMetrics(){const report=operationalReports.find(item=>item.report_type==='DAILY');if(!report)return;const metrics=report.metrics||{};const reportKpis=document.querySelectorAll('.report-kpis strong');if(reportKpis[0])reportKpis[0].textContent=String(metrics.operations||0);if(reportKpis[1])reportKpis[1].textContent=`${operations.reduce((sum,item)=>sum+Number(item.tons||0),0)} t`;const status=document.querySelector('.report-status');if(status)status.textContent='● DADOS DO BANCO';}
async function loadRemoteState(){if(!supabaseClient||!authenticatedUser)return;const [operationsResult,docksResult,eventsResult,reportsResult]=await Promise.all([supabaseClient.from('operations').select('*').order('operation_date',{ascending:false}),supabaseClient.from('docks').select('*').order('number'),supabaseClient.from('operation_events').select('*').order('created_at',{ascending:true}),supabaseClient.from('operational_reports').select('*').order('period_start',{ascending:false}).limit(12)]);if(operationsResult.error||docksResult.error||eventsResult.error){toast('Nao foi possivel carregar os dados do servidor');return;}operations.splice(0,operations.length,...(operationsResult.data||[]).map(fromRemoteOperation));docks.splice(0,docks.length,...(docksResult.data||[]));operationEvents.splice(0,operationEvents.length,...(eventsResult.data||[]).map(event=>({dt:event.operation_id,eventType:event.event_type,timestamp:event.created_at,observation:event.observation,user:event.user_id})));operationalReports.splice(0,operationalReports.length,...(reportsResult.data||[]));render();applyReportMetrics();updateNotificationBadge();}
function subscribeToRemoteState(){supabaseClient.channel('torre-sul-operational-state').on('postgres_changes',{event:'*',schema:'public',table:'operations'},loadRemoteState).on('postgres_changes',{event:'*',schema:'public',table:'docks'},loadRemoteState).on('postgres_changes',{event:'*',schema:'public',table:'operation_events'},loadRemoteState).subscribe();}
async function clearAllData(){if(!window.confirm('Apagar todas as operacoes e o historico? Esta acao nao pode ser desfeita.'))return;if(!authenticatedUser)return;const result=await supabaseClient.from('operations').delete().not('dt','is',null);if(result.error){toast('Nao foi possivel apagar os dados do servidor');return;}operations.splice(0,operations.length);operationEvents.splice(0,operationEvents.length);render();updateNotificationBadge();toast('Todos os dados foram apagados');}
async function saveRemoteOperation(operation){if(!authenticatedUser)return;const payload={dt:operation.dt,operation_date:operation.date.split('/').reverse().join('-'),plate:operation.plate,client:operation.client,carrier:operation.carrier,driver:operation.driver,tons:operation.tons||null,uf:operation.uf||null,load_type:operation.loadType||null,history_problem:operation.historyProblem||null,guide_call:operation.guideCall||null,delivery_info:operation.deliveryInfo||null,otm_date:operation.otmDate||null,otm_time:operation.otmTime||null,horse_plate:operation.horsePlate||null,composition:operation.composition||null,operation_type:operation.type,dock_number:operation.dock==='-'?null:operation.dock.replace('DOCA ',''),start_time:operation.start==='-'?null:operation.start,elapsed:operation.elapsed,sla:operation.sla,status:operation.status,risk:operation.risk,tone:operation.tone,age:operation.age,next_action:operation.next,last_action:operation.lastAction,arrival_at:operation.arrivalAt||null,cd_entry_at:operation.cdEntryAt||null,dock_at:operation.dockAt||null,operation_started_at:operation.operationStartedAt||null,operation_finished_at:operation.operationFinishedAt||null,exited_at:operation.exitedAt||null,updated_at:new Date().toISOString()};const result=await supabaseClient.from('operations').upsert(payload,{onConflict:'dt'}).select().single();if(result.error){toast('Erro ao salvar operacao no servidor');return null;}operation.id=result.data.id;return result.data;}
async function recordEvent(operation,eventType,observation){const saved=await saveRemoteOperation(operation);if(!saved)return false;const result=await supabaseClient.from('operation_events').insert({operation_id:saved.id,event_type:eventType,observation,user_id:authenticatedUser.id});if(result.error){toast('Operacao salva, mas evento nao foi registrado');return false;}await syncRemoteDocks();return true;}
async function syncRemoteDocks(){if(!authenticatedUser)return;const result=await supabaseClient.from('docks').upsert(docks.map(dock=>({number:dock.number,state:dock.state,updated_at:new Date().toISOString()})),{onConflict:'number'});if(result.error)toast('Erro ao salvar docas no servidor');}
async function syncRemoteState(){await Promise.all([syncRemoteDocks(),...operations.map(saveRemoteOperation)]);}
async function remoteActionOperation(dt,action){const operation=operations.find(item=>item.dt===dt);if(!operation||!authenticatedUser)return;const allowed={chegada:['AGUARDANDO'],patio:['NO PATIO'],doca:['NO CD','AGUARDANDO DOCA'],inicio:['NA DOCA'],finalizar:['CARREGAMENTO EM ANDAMENTO','DESCARGA EM ANDAMENTO'],saida:['CARREGAMENTO FINALIZADO','DESCARGA FINALIZADA','AGUARDANDO SAIDA']};if(allowed[action]&&!allowed[action].some(status=>operation.status.includes(status))){toast('Acao bloqueada: respeite a ordem da operacao');return;}const now=new Date().toISOString();const actions={chegada:['NO PATIO','REGISTRAR CHEGADA','arrivalAt'],patio:['NO CD','ENTRAR NO CD','cdEntryAt'],doca:['NA DOCA','ALOCAR DOCA','dockAt'],inicio:[operation.type==='DESCARGA'?'DESCARGA EM ANDAMENTO':'CARREGAMENTO EM ANDAMENTO','INICIAR OPERACAO','operationStartedAt'],finalizar:[operation.type==='DESCARGA'?'DESCARGA FINALIZADA':'CARREGAMENTO FINALIZADO','FINALIZAR OPERACAO','operationFinishedAt'],saida:['SAIDA REALIZADA','REGISTRAR SAIDA','exitedAt']};const transition=actions[action];if(!transition)return;if(action==='doca'){const available=docks.find(dock=>dock.state==='free');if(operation.dock==='-'){if(!available){toast('Nenhuma doca disponivel');return;}operation.dock=`DOCA ${available.number}`;available.state='busy';}else if(docks.find(dock=>dock.number===operation.dock.replace('DOCA ',''))?.state==='busy'){toast('Doca ja ocupada');return;}}if(action==='saida'){const releasedDock=docks.find(dock=>dock.number===operation.dock.replace('DOCA ',''));if(releasedDock)releasedDock.state='free';operation.dock='-';}operation.status=transition[0];operation.next=nextAction(operation);operation.lastAction=now.slice(11,16);operation[transition[2]]=now;const saved=await saveRemoteOperation(operation);if(!saved){await loadRemoteState();return;}const eventResult=await supabaseClient.from('operation_events').insert({operation_id:saved.id,event_type:transition[1],observation:`Acao registrada as ${now}`,user_id:authenticatedUser.id});if(eventResult.error){await loadRemoteState();toast('Falha ao registrar evento; alteracao revertida');return;}if(action==='doca'||action==='saida')await syncRemoteDocks();await loadRemoteState();toast(`${transition[1]}: ${operation.dt}`);}
function actionOperation(dt,action){const operation=operations.find(item=>item.dt===dt);if(!operation)return;const allowed={chegada:['AGUARDANDO'],doca:['NO PATIO','AGUARDANDO DOCA'],inicio:['NA DOCA'],finalizar:['CARREGAMENTO EM ANDAMENTO','DESCARGA EM ANDAMENTO'],saida:['CARREGAMENTO FINALIZADO','DESCARGA FINALIZADA','AGUARDANDO SAIDA']};if(allowed[action]&&!allowed[action].some(status=>operation.status.includes(status))){toast('Acao bloqueada: respeite a ordem da operacao');return;}const now=new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'});const actions={chegada:['NO PATIO','REGISTRAR CHEGADA'],patio:['NO PATIO','ENTRAR NO PATIO'],doca:['NA DOCA','ALOCAR DOCA'],inicio:[operation.type==='DESCARGA'?'DESCARGA EM ANDAMENTO':'CARREGAMENTO EM ANDAMENTO','INICIAR OPERACAO'],finalizar:[operation.type==='DESCARGA'?'DESCARGA FINALIZADA':'CARREGAMENTO FINALIZADO','FINALIZAR OPERACAO'],saida:['SAIDA REALIZADA','REGISTRAR SAIDA']};const transition=actions[action];if(!transition)return;if(action==='doca'){const currentDock=docks.find(d=>d.number===operation.dock.replace('DOCA ',''));if(operation.dock==='-'){const available=docks.find(d=>d.state==='free');if(!available){toast('Nenhuma doca disponivel');return}operation.dock='DOCA '+available.number;available.state='busy';}else if(currentDock?.state==='busy'){toast('Doca ja ocupada');return;}}if(action==='saida'){const releasedDock=docks.find(d=>d.number===operation.dock.replace('DOCA ',''));if(releasedDock)releasedDock.state='free';operation.dock='-';operation.status='SAIDA REALIZADA';}else operation.status=transition[0];operation.next=nextAction(operation);operation.lastAction=now;recordEvent(operation,transition[1],`Acao registrada as ${now}`);toast(`${transition[1]}: ${operation.dt}`);render();}
const docks = Array.from({length:11}, (_, index) => ({number:String(index+1).padStart(2,'0'), state:['busy','free','free','busy','busy','free','blocked','busy','free','free','reserved'][index]}));
const views = {dashboard:'Dashboard', 'tempo-real':'Tempo Real', programacao:'Programacao', carregamento:'Carregamento', descarga:'Descarga', docas:'Docas', 'operacao-mobile':'Operacao Mobile', gerencial:'Gerencial', historico:'Historico', configuracoes:'Configuracoes'};
