const transitionAction=actionOperation; actionOperation=(dt,action)=>{const operation=operations.find(item=>item.dt===dt);if(operation&&action==='chegada'&&operation.status==='NO PATIO')action='doca';return transitionAction(dt,action);}; actionOperation=remoteActionOperation; const remoteActionWithSequence=actionOperation; actionOperation=(dt,action)=>{const operation=operations.find(item=>item.dt===dt);if(operation&&action==='chegada'&&operation.status==='NO PATIO')action='patio';if(operation&&action==='chegada'&&operation.status==='NO CD')action='doca';return remoteActionWithSequence(dt,action);};
const toast = message => { const node=document.querySelector('#toast'); node.textContent=message; node.classList.add('show'); setTimeout(()=>node.classList.remove('show'),2600); };
function refreshDashboard(button){button.classList.add('is-refreshing');button.disabled=true;setTimeout(()=>{button.classList.remove('is-refreshing');button.disabled=false;render();toast('Dashboard atualizado agora');},650);}
function updateClock(){const clock=document.querySelector('#live-clock');if(clock)clock.textContent=new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',second:'2-digit'});}
function showNotifications(){let panel=document.querySelector('#notifications-popover');if(panel){panel.classList.toggle('open');return;}panel=document.createElement('section');panel.id='notifications-popover';panel.innerHTML=`<div class="notification-head"><strong>NOTIFICACOES</strong><button onclick="closeNotifications()">×</button></div><div class="notification-summary">3 alertas exigem acompanhamento</div><button class="notification-item critical" onclick="closeNotifications();openOperationDetail('DT 1394701')"><span class="notification-icon">!</span><span><b>SLA PERDIDO</b><small>DT 1394701 · +18 min acima do limite</small></span><i>→</i></button><button class="notification-item warning" onclick="closeNotifications();openOperationDetail('DT 1394728')"><span class="notification-icon">!</span><span><b>SLA EM RISCO</b><small>DT 1394728 · 18 min restantes</small></span><i>→</i></button><button class="notification-item warning" onclick="closeNotifications();location.hash='descarga'"><span class="notification-icon">!</span><span><b>PATIO EXCEDIDO</b><small>DT 1394762 · aguardando doca</small></span><i>→</i></button><div class="notification-foot" onclick="closeNotifications();location.hash='tempo-real'">VER TODAS AS NOTIFICACOES →</div>`;document.body.appendChild(panel);requestAnimationFrame(()=>panel.classList.add('open'));}
function closeNotifications(){document.querySelector('#notifications-popover')?.classList.remove('open');}
function openOperationDetail(dt){const operation=operations.find(item=>item.dt===dt);if(!operation)return;let modal=document.querySelector('#operation-modal');if(!modal){modal=document.createElement('div');modal.id='operation-modal';document.body.appendChild(modal);}modal.innerHTML=`<div class="modal-backdrop" onclick="closeOperationDetail()"></div><section class="detail-modal"><button class="modal-close" onclick="closeOperationDetail()">×</button><p class="eyebrow">DETALHE DA OPERACAO</p><h2>${operation.dt}</h2><div class="detail-status"><span class="status ${operation.tone}"><i></i>${operation.status}</span><span class="risk ${operation.risk}">${operation.risk==='red'?'SLA PERDIDO':operation.risk==='orange'?'EM ATENCAO':'NORMAL'}</span></div><div class="detail-grid"><span>DATA<strong>${operation.date}</strong></span><span>PLACA<strong>${operation.plate}</strong></span><span>CLIENTE<strong>${operation.client}</strong></span><span>TRANSPORTADORA<strong>${operation.carrier}</strong></span><span>MOTORISTA<strong>${operation.driver}</strong></span><span>DOCA<strong>${operation.dock}</strong></span><span>TEMPO<strong>${operation.elapsed}</strong></span><span>SLA<strong>${operation.sla}</strong></span></div><div class="timeline-mini"><b>08:10</b> PROGRAMADO <b>08:32</b> CHEGADA <b>08:45</b> PATIO <b>09:03</b> DOCA <b>09:07</b> INICIO</div><button class="btn btn-primary" onclick="closeOperationDetail();toast('${nextAction(operation)} para ${operation.dt}')">${nextAction(operation)} →</button></section>`;modal.classList.add('open');}
function closeOperationDetail(){document.querySelector('#operation-modal')?.classList.remove('open');}
const slaRules = {batido:120,paletizado:90};
function saoPauloNow(){return new Date(new Date().toLocaleString('en-US',{timeZone:'America/Sao_Paulo'}));}
function getTurno(value){const date=value?saoPauloDate(value):saoPauloNow();const minutes=date.getHours()*60+date.getMinutes();if(minutes>=330&&minutes<820)return 'T1';if(minutes>=820&&minutes<1320)return 'T2';return 'T3';}
function saoPauloDate(value){return new Date(new Date(value).toLocaleString('en-US',{timeZone:'America/Sao_Paulo'}));}
function formatDate(date){return date.toLocaleDateString('pt-BR',{day:'2-digit',month:'2-digit',year:'numeric'});}
function formatDateLong(date){return date.toLocaleDateString('pt-BR',{day:'2-digit',month:'short',year:'numeric'}).replace('.','').toUpperCase();}
function currentOperationalWeek(){const now=saoPauloNow();const start=new Date(now);const day=start.getDay();const offset=day===0?0:day;start.setDate(start.getDate()-offset);start.setHours(22,0,0,0);if(now<start)start.setDate(start.getDate()-7);const end=new Date(start);end.setDate(end.getDate()+6);return {start,end};}
function currentPeriod(){const now=saoPauloNow();const week=currentOperationalWeek();return {now,week,turno:getTurno(now),date:formatDateLong(now)};}
function calculateRisk(percent){return percent>=100?'SLA PERDIDO':percent>=90?'CRITICO':percent>=70?'ATENCAO':'NORMAL';}
function nextAction(operation){const status=operation.status;if(status==='AGUARDANDO')return 'REGISTRAR CHEGADA';if(status==='NO PATIO')return 'ENTRAR NO CD';if(status==='NO CD')return 'ALOCAR DOCA';if(status==='AGUARDANDO DOCA')return 'ALOCAR DOCA';if(status==='NA DOCA')return 'INICIAR OPERACAO';if(status.includes('EM ANDAMENTO'))return operation.type==='DESCARGA'?'FINALIZAR DESCARGA':'FINALIZAR CARREGAMENTO';if(status.includes('FINALIZADO')||status==='AGUARDANDO SAIDA')return 'REGISTRAR SAIDA';return operation.next || 'ACOMPANHAR OPERACAO';}
function isActiveOperation(operation){return operation.status!=='SAIDA REALIZADA';}
function previousPendingBanner(type){const pending=operations.filter(operation=>isActiveOperation(operation)&&operation.type===type&&operation.age==='historical');if(!pending.length)return '';return `<div class="realtime-alert"><span>△</span><strong>${pending.length} veiculo(s) de ${pending.length===1?'dia anterior':'dias anteriores'} pendente(s) de finalizacao</strong><button onclick="location.hash='historico'">VER LISTA</button></div>`;}
function showOperation(dt){const operation=operations.find(item=>item.dt===dt); if(operation) toast(`${operation.dt}: ${nextAction(operation)}`);}
function editDock(number){const dock=docks.find(item=>item.number===number);if(!dock)return;let modal=document.querySelector('#dock-editor');if(!modal){modal=document.createElement('div');modal.id='dock-editor';document.body.appendChild(modal);}modal.innerHTML=`<div class="modal-backdrop" onclick="closeDockEditor()"></div><section class="dock-editor-modal"><button class="modal-close" onclick="closeDockEditor()">×</button><p class="eyebrow">CONFIGURACAO OPERACIONAL</p><h2>EDITAR DOCA ${number}</h2><p class="modal-description">Defina o status atual desta posicao operacional.</p><label class="dock-status-label">STATUS DA DOCA<select id="dock-status-select"><option value="free">DISPONIVEL</option><option value="busy">OCUPADA</option><option value="blocked">BLOQUEADA</option><option value="reserved">RESERVADA</option></select></label><div class="dock-editor-actions"><button class="btn" onclick="closeDockEditor()">CANCELAR</button><button class="btn btn-primary" onclick="saveDockEdit('${number}')">SALVAR ALTERACAO</button></div></section>`;modal.classList.add('open');modal.querySelector('#dock-status-select').value=dock.state;}
function closeDockEditor(){document.querySelector('#dock-editor')?.classList.remove('open');}
function saveDockEdit(number){const dock=docks.find(item=>item.number===number);const state=document.querySelector('#dock-status-select')?.value;if(!dock||!state)return;if(state==='busy'&&!operations.some(operation=>operation.dock==='DOCA '+number&&operation.status!=='SAIDA REALIZADA')){toast('Alocacao de veiculo deve ser feita pela operacao');return;}dock.state=state;persistState();closeDockEditor();render();toast(`DOCA ${number} atualizada`);}
function applyFilters(){const type=document.querySelector('#operation-filter')?.value||'all'; const status=document.querySelector('#status-filter')?.value||'all'; document.querySelectorAll('[data-operation]').forEach(row=>{const operation=operations.find(item=>item.dt===row.dataset.operation); row.hidden=(type!=='all'&&operation.type!==type)||(status!=='all'&&operation.risk!==status);});}
function header(title='DASHBOARD OPERACIONAL', subtitle='Visao consolidada da operacao da unidade') { return `<div class="page-head"><div><p class="eyebrow">TORRE SUL / CENTRO DE COMANDO</p><h1>${title}</h1><p class="subtitle">${subtitle}</p></div><div class="head-meta"><span class="date-box"><strong>26 AGO 2026</strong><br>QUARTA-FEIRA</span><span><strong>TURNO T2</strong><br>13:40 - 22:00 <b class="clock" id="live-clock"></b></span><button class="btn btn-primary refresh-button" onclick="refreshDashboard(this)">↻ ATUALIZAR</button></div></div>`; }
const staticHeader=header;header=(title='DASHBOARD OPERACIONAL',subtitle='Visao consolidada da operacao da unidade')=>{const period=currentPeriod();return staticHeader(title,subtitle).replace('26 AGO 2026',period.date).replace('QUARTA-FEIRA',period.now.toLocaleDateString('pt-BR',{weekday:'long'}).toUpperCase()).replace('TURNO T2',`TURNO ${period.turno}`);};
function filters(){const period=currentPeriod();return `<div class="filter-bar"><select class="filter"><option>Hoje, ${period.date}</option></select><select class="filter"><option>Todos os turnos</option><option>T1</option><option>T2</option><option>T3</option></select><select class="filter" id="operation-filter" onchange="applyFilters()"><option value="all">Todas as operacoes</option><option value="CARREGAMENTO">Carregamento</option><option value="DESCARGA">Descarga</option></select><select class="filter"><option>Todos os clientes</option><option>Sul Quimica</option><option>Mercado Sul</option></select><select class="filter" id="status-filter" onchange="applyFilters()"><option value="all">Todos os status</option><option value="red">SLA perdido</option><option value="orange">Em risco</option></select><span class="filter-clear" onclick="document.querySelectorAll('.filter').forEach(select=>select.selectedIndex=0);applyFilters();toast('Filtros limpos')">LIMPAR FILTROS</span></div>`;}
function kpis(){return `<div class="kpis"><div class="kpi" style="--accent:var(--blue)" onclick="toast('48 veiculos programados hoje')"><div class="kpi-label">VEICULOS DO DIA</div><div class="kpi-value">48</div><div class="kpi-note"><b>+12%</b> vs. ontem</div></div><div class="kpi" style="--accent:var(--green)"><div class="kpi-label">FINALIZADOS</div><div class="kpi-value">29</div><div class="kpi-note">60% do programado</div></div><div class="kpi" style="--accent:var(--blue)"><div class="kpi-label">EM OPERACAO</div><div class="kpi-value">07</div><div class="kpi-note">04 carga / 03 descarga</div></div><div class="kpi" style="--accent:var(--orange)"><div class="kpi-label">AGUARDANDO</div><div class="kpi-value">12</div><div class="kpi-note">08 patio / 04 doca</div></div><div class="kpi" style="--accent:var(--muted)"><div class="kpi-label">JA SAIRAM</div><div class="kpi-value">26</div><div class="kpi-note">54% da programacao</div></div><div class="kpi" style="--accent:var(--orange)"><div class="kpi-label">NO PATIO</div><div class="kpi-value">08</div><div class="kpi-note">03 acima de 30 min</div></div><div class="kpi" style="--accent:var(--orange)"><div class="kpi-label">VOLUME MOVIMENTADO</div><div class="kpi-value">184<span style="font-size:19px"> t</span></div><div class="kpi-note">2.460 fardos</div></div><div class="kpi" style="--accent:var(--red)" onclick="location.hash='tempo-real'"><div class="kpi-label">ALERTAS ATIVOS</div><div class="kpi-value">04</div><div class="kpi-note">1 critico / 3 atencao</div></div><div class="kpi" style="--accent:var(--green)"><div class="kpi-label">SLA</div><div class="kpi-value">91<span style="font-size:19px">%</span></div><div class="kpi-note"><b>+4.8%</b> vs. ontem</div></div><div class="kpi" style="--accent:var(--yellow)"><div class="kpi-label">BACKLOG</div><div class="kpi-value">06</div><div class="kpi-note">2 pendencias antigas</div></div></div>`;}
function kpis(){return `<div class="kpis compact-kpis"><div class="kpi" style="--accent:var(--orange)" onclick="toast('48 veiculos programados hoje')"><div class="kpi-label">VEICULOS DO DIA</div><div class="kpi-value">48</div></div><div class="kpi" style="--accent:var(--green)"><div class="kpi-label">FINALIZADOS</div><div class="kpi-value">29</div></div><div class="kpi" style="--accent:var(--blue)"><div class="kpi-label">EM OPERACAO</div><div class="kpi-value">07</div></div><div class="kpi" style="--accent:var(--yellow)"><div class="kpi-label">AGUARDANDO</div><div class="kpi-value">12</div></div><div class="kpi" style="--accent:var(--muted)"><div class="kpi-label">JA SAIRAM</div><div class="kpi-value">26</div></div></div>`;}
const baseKpis=kpis;kpis=()=>baseKpis().replace('48 veiculos programados hoje',`${operations.length} veiculos registrados hoje`);
function alerts(){return `<section class="panel"><div class="panel-head"><span class="panel-title">ALERTAS ATIVOS</span><span class="text-link">VER TODOS →</span></div><div class="alerts"><div class="alert"><span class="alert-mark"></span><div><div class="alert-title">SLA PERDIDO · DT 1394701</div><div class="alert-copy"><b>Descarga · Doca 08</b> · aguardando tratativa</div></div><div class="alert-time">+18 min<small>excedente</small></div></div><div class="alert warn"><span class="alert-mark"></span><div><div class="alert-title">SLA EM RISCO · DT 1394728</div><div class="alert-copy"><b>Carregamento · Doca 02</b> · 18 min restantes</div></div><div class="alert-time">01:42<small>de 02:00</small></div></div><div class="alert warn"><span class="alert-mark"></span><div><div class="alert-title">PATIO EXCEDIDO · DT 1394762</div><div class="alert-copy"><b>Sem doca alocada</b> · limite de 30 min</div></div><div class="alert-time">+04 min<small>excedente</small></div></div></div></section>`;}
function table(){return `<section class="panel table-panel"><div class="panel-head"><span class="panel-title">OPERACOES EM ACOMPANHAMENTO</span><span class="panel-meta">Ordenadas por risco · ${operations.length} registros</span></div><div class="table-wrap"><table class="operations"><thead><tr><th>DT / DATA</th><th>STATUS</th><th>OPERACAO</th><th>PLACA</th><th>CLIENTE</th><th>DOCA</th><th>TEMPO / SLA</th><th>RISCO</th><th>PROXIMA ACAO</th></tr></thead><tbody>${operations.map(o=>`<tr data-operation="${o.dt}"><td><span class="dt">${o.dt}</span><br><span class="muted">${o.date}</span></td><td><span class="status ${o.tone}"><i></i>${o.status}</span></td><td>${o.type}</td><td>${o.plate}</td><td>${o.client}</td><td>${o.dock}</td><td>${o.elapsed}<br><span class="muted">SLA ${o.sla}</span></td><td class="risk ${o.risk}">${o.risk==='red'?'PERDIDO':o.risk==='orange'?'ATENCAO':'NORMAL'}</td><td><button class="btn" onclick="showOperation('${o.dt}')">${nextAction(o)}</button></td></tr>`).join('')}</tbody></table></div></section>`;}
function pendingCards(){const active=operations.filter(isActiveOperation);return `<section class="pending-section"><div class="section-heading"><span class="alert-symbol">△</span><span>PENDENTES DE FINALIZACAO (${active.length})</span></div><div class="pending-grid">${active.map(o=>`<article class="pending-card ${o.risk}" data-operation="${o.dt}" onclick="openOperationDetail('${o.dt}')"><div class="pending-top"><strong>${o.dt}</strong><span class="pending-badge ${o.tone}">${o.status}</span></div><div class="pending-meta">${o.date} · Placa ${o.plate} · ${o.client}</div><div class="pending-foot"><span>${o.dock === '-' ? 'Sem doca' : o.dock} · ${o.type}</span><span class="risk ${o.risk}">${o.age==='historical'?'Pendente ha 7 dias':o.risk==='red'?'SLA perdido':o.elapsed}</span></div><button class="pending-action" onclick="event.stopPropagation();showOperation('${o.dt}')">${nextAction(o)} →</button></article>`).join('')}</div></section>`;}
function dockPanel(){return `<section class="panel table-panel"><div class="panel-head"><span class="panel-title">OCUPACAO DE DOCAS</span><span class="panel-meta">04 ocupadas · 11 total</span></div><div class="dock-grid">${docks.map(d=>{const text=d.state==='busy'?'OCUPADA':d.state==='blocked'?'BLOQUEADA':d.state==='reserved'?'RESERVADA':'DISPONIVEL'; const op=d.state==='busy'?operations.find(o=>o.dock==='DOCA '+d.number):null; return `<div class="dock ${d.state}"><div class="dock-top">DOCA ${d.number}<span class="dock-state">${text}</span></div><div class="dock-info">${op?`<b>${op.dt}</b><br>${op.type} · ${op.plate}<br>Tempo ${op.elapsed}`:d.state==='blocked'?'Manutencao programada':d.state==='reserved'?'Reservada para operacao':'Pronta para alocacao'}</div><button class="dock-edit" onclick="editDock('${d.number}')">EDITAR</button></div>`}).join('')}</div></section>`;}
function renderDashboard(){page.innerHTML=header()+kpis()+`<div class="summary-row"><section class="panel summary-card"><div class="panel-head"><span class="panel-title">VOLUME MOVIMENTADO</span><span class="summary-icon orange">◇</span></div><div class="summary-value">184 <small>t</small></div><div class="summary-note">2.460 fardos</div></section><section class="panel summary-card clickable-summary" onclick="showNotifications()"><div class="panel-head"><span class="panel-title">ALERTAS ATIVOS</span><span class="summary-icon green">△</span></div><div class="summary-value">04</div><div class="summary-note">1 critico · 3 em atencao</div></section></div>${pendingCards()}<section class="panel movement"><div class="panel-head"><span class="panel-title">MOVIMENTACAO DO DIA</span><span class="panel-meta">26/08/2026 · Turno T2</span></div><div class="movement-content"><strong>42</strong> veiculos em movimentacao · <span>07 em operacao</span> · <span>29 finalizados</span></div></section>`;updateClock();}
function realtimeTable(){const ordered=operations.filter(isActiveOperation).sort((a,b)=>({red:0,orange:1,green:2}[a.risk]-({red:0,orange:1,green:2}[b.risk]))); return `<section class="panel realtime-table"><div class="panel-head"><span class="panel-title">OPERACOES EM TEMPO REAL</span><span class="panel-meta">Atualizacao automatica · agora</span></div><div class="table-wrap"><table class="operations"><thead><tr><th>DT</th><th>STATUS</th><th>OPERACAO</th><th>PLACA</th><th>CLIENTE</th><th>DOCA</th><th>TEMPO</th><th>SLA</th><th>RISCO</th><th>PROXIMA ACAO</th></tr></thead><tbody>${ordered.map(o=>`<tr data-operation="${o.dt}"><td class="dt">${o.dt}<br><span class="muted">${o.date}</span></td><td><span class="status ${o.tone}"><i></i>${o.status}</span></td><td>${o.type}</td><td>${o.plate}</td><td>${o.client}</td><td>${o.dock}</td><td>${o.elapsed}</td><td class="muted">${o.sla}</td><td class="risk ${o.risk}">${o.risk==='red'?'PERDIDO':o.risk==='orange'?'ATENCAO':'NORMAL'}</td><td><button class="btn" onclick="showOperation('${o.dt}')">${nextAction(o)}</button></td></tr>`).join('')}</tbody></table></div></section>`;}
function renderRealtime(){page.innerHTML=header('PAINEL EM TEMPO REAL','Veiculos e excecoes operacionais · atualizacao automatica')+`<div class="realtime-alert"><span>△</span><strong>6 veiculo(s) de dias anteriores pendentes de finalizacao</strong><button onclick="toast('Lista de pendencias aberta')">VER LISTA</button></div><div class="realtime-filters"><input class="search-input" id="realtime-search" placeholder="Buscar DT, placa, cliente..." oninput="filterRealtime()"><select class="filter" id="realtime-status" onchange="filterRealtime()"><option value="all">Todos os status</option><option value="red">SLA perdido</option><option value="orange">Em risco</option><option value="green">Normal</option></select><span class="realtime-count">● 07 em operacao · 12 aguardando · 03 em risco</span></div>${realtimeTable()}`;}
function filterRealtime(){const query=(document.querySelector('#realtime-search')?.value||'').toLowerCase(); const status=document.querySelector('#realtime-status')?.value||'all'; document.querySelectorAll('.realtime-table tbody tr').forEach(row=>{const operation=operations.find(item=>item.dt===row.dataset.operation); row.hidden=!(`${operation.dt} ${operation.plate} ${operation.client}`.toLowerCase().includes(query)||(query==='' ))||(status!=='all'&&operation.risk!==status);});}
function operationCard(operation){const action=operation.status==='AGUARDANDO DOCA'?'ALOCAR DOCA':operation.status==='NA DOCA'?'INICIAR '+operation.type:operation.status==='DESCARGA EM ANDAMENTO'?'FINALIZAR DESCARGA':operation.status==='CARREGAMENTO EM ANDAMENTO'?'FINALIZAR CARREGAMENTO':operation.status.includes('FINALIZADO')||operation.status==='AGUARDANDO SAIDA'?'REGISTRAR SAIDA':'REGISTRAR CHEGADA';const actionKey=operation.status==='AGUARDANDO DOCA'?'doca':operation.status==='NA DOCA'?'inicio':operation.status.includes('EM ANDAMENTO')?'finalizar':operation.status.includes('FINALIZADO')||operation.status==='AGUARDANDO SAIDA'?'saida':'chegada'; return `<article class="operation-card ${operation.risk}" data-operation="${operation.dt}"><div class="operation-card-head"><span class="old-label">${operation.age==='historical'?'PENDENCIA DE '+operation.date:''}</span><span class="pending-badge ${operation.tone}">${operation.status}</span></div><div class="operation-card-title">${operation.dt}</div><div class="operation-card-sub">Placa ${operation.plate} · ${operation.client} · ${operation.carrier}</div><div class="operation-card-details"><span>Motorista: <b>${operation.driver}</b></span><span>Chegada: <b>${operation.start==='-'?'--:--':operation.start}</b></span><span>Doca: <b>${operation.dock}</b></span><span>Inicio: <b>${operation.start==='-'?'--:--':operation.start}</b></span><span>Final: <b>--:--</b></span><span>Saida: <b>--:--</b></span><span>Permanencia: <b>${operation.elapsed}</b></span><span>Tempo op.: <b>${operation.elapsed}</b></span></div><div class="operation-actions"><button class="btn secondary-action" onclick="actionOperation('${operation.dt}','chegada')">REGISTRAR CHEGADA</button><button class="btn edit-action" onclick="toast('Edicao de placa aberta')">EDITAR PLACA</button><button class="btn btn-primary" onclick="actionOperation('${operation.dt}','${actionKey}')">${action}</button><button class="btn" onclick="actionOperation('${operation.dt}','finalizar')">FINALIZAR</button><button class="btn" onclick="actionOperation('${operation.dt}','saida')">REGISTRAR SAIDA</button></div></article>`;}
function renderOperationBoard(type){const items=operations.filter(operation=>operation.type===type); const title=type==='DESCARGA'?'DESCARGA':'CARREGAMENTO'; page.innerHTML=header(title,`Veiculos em operacao de ${title.toLowerCase()}`)+`<div class="realtime-alert"><span>△</span><strong>6 veiculo(s) de dias anteriores pendentes de finalizacao</strong><button onclick="toast('Lista de pendencias aberta')">VER LISTA</button></div><div class="operation-board-filters"><input class="search-input" placeholder="Buscar DT, placa, cliente..." oninput="filterOperationBoard(this)"><select class="filter" onchange="filterOperationBoard(this)"><option value="all">Todos os status</option><option value="red">SLA perdido</option><option value="orange">Em risco</option><option value="green">Normal</option></select></div><div class="operation-board">${items.map(operationCard).join('')}</div>`;}
function filterOperationBoard(control){const board=control.closest('.page'); const query=board.querySelector('.search-input').value.toLowerCase(); const status=board.querySelector('.operation-board-filters select').value; board.querySelectorAll('.operation-card').forEach(card=>{const operation=operations.find(item=>item.dt===card.dataset.operation); card.hidden=!(`${operation.dt} ${operation.plate} ${operation.client}`.toLowerCase().includes(query))||(status!=='all'&&operation.risk!==status);});}
const baseRenderOperationBoard=renderOperationBoard; renderOperationBoard=type=>{baseRenderOperationBoard(type);document.querySelectorAll('.realtime-alert').forEach(alert=>alert.remove());document.querySelector('.operation-board-filters')?.insertAdjacentHTML('beforebegin',previousPendingBanner(type));document.querySelectorAll('.operation-card').forEach(card=>{const operation=operations.find(item=>item.dt===card.dataset.operation);if(operation&&!isActiveOperation(operation))card.remove();});};
const baseRenderRealtime=renderRealtime; renderRealtime=()=>{baseRenderRealtime();document.querySelectorAll('.realtime-alert').forEach(alert=>alert.remove());const anchor=document.querySelector('.realtime-filters');if(anchor){anchor.insertAdjacentHTML('beforebegin',previousPendingBanner('DESCARGA')+previousPendingBanner('CARREGAMENTO'));}};
renderHistory=()=>{const closed=operations.filter(operation=>!isActiveOperation(operation));const visible=closed.length?closed:operations;page.innerHTML=header('HISTORICO OPERACIONAL','Relatorio diario compilado e rastreavel da operacao')+`<div class="history-toolbar"><label>DATA DO RELATORIO<input type="date" value="2026-08-26"></label><input class="search-input" id="history-search" placeholder="Buscar DT, placa, cliente, motorista..." oninput="filterHistory()"><select class="filter" id="history-type" onchange="filterHistory()"><option value="all">Todas as operacoes</option><option value="CARREGAMENTO">Carregamento</option><option value="DESCARGA">Descarga</option></select><button class="btn btn-primary" onclick="toast('Relatorio diario exportado')">EXPORTAR RELATORIO</button></div><section class="report-banner"><div><span>RELATORIO DIARIO</span><strong>26 DE AGOSTO DE 2026</strong><small>Consolidado operacional · ${closed.length} operacoes encerradas</small></div><div class="report-status">● DADOS COMPILADOS</div></section><div class="history-kpis"><div><span>OPERACOES ENCERRADAS</span><strong>${closed.length||0}</strong></div><div><span>TONELADAS</span><strong>184 t</strong></div><div><span>FARDOS</span><strong>2.460</strong></div><div><span>EVENTOS REGISTRADOS</span><strong>${operationEvents.length}</strong></div></div><section class="panel history-report-table"><div class="panel-head"><span class="panel-title">REGISTROS DO RELATORIO</span><span class="panel-meta">Clique em uma DT para abrir o detalhe</span></div><div class="table-wrap"><table class="operations"><thead><tr><th>DT / DATA</th><th>OPERACAO</th><th>PLACA</th><th>CLIENTE</th><th>TRANSPORTADORA</th><th>STATUS</th><th>SAIDA</th><th></th></tr></thead><tbody>${visible.map(operation=>`<tr data-history-operation="${operation.dt}"><td class="dt">${operation.dt}<br><span class="muted">${operation.date}</span></td><td>${operation.type}</td><td>${operation.plate}</td><td>${operation.client}</td><td>${operation.carrier}</td><td><span class="status green"><i></i>${operation.status}</span></td><td>${operation.status==='SAIDA REALIZADA'?'Registrada':'Pendente'}</td><td><button class="btn" onclick="openOperationDetail('${operation.dt}')">ABRIR</button></td></tr>`).join('')}</tbody></table></div></section>`;};
function filterHistory(){const query=(document.querySelector('#history-search')?.value||'').toLowerCase();const type=document.querySelector('#history-type')?.value||'all';document.querySelectorAll('[data-history-operation]').forEach(row=>{const operation=operations.find(item=>item.dt===row.dataset.historyOperation);row.hidden=!(`${operation.dt} ${operation.plate} ${operation.client} ${operation.driver}`.toLowerCase().includes(query))||(type!=='all'&&operation.type!==type);});}
const baseHistoryView=renderHistory;renderHistory=()=>{if(operations.length){baseHistoryView();return;}page.className='page managerial-page';page.innerHTML=header('HISTORICO OPERACIONAL','Relatorio diario compilado e rastreavel da operacao')+`<div class="report-banner"><div><span>RELATORIO DIARIO</span><strong>26 DE AGOSTO DE 2026</strong><small>Nenhuma operacao registrada no periodo</small></div><div class="report-status">● SEM REGISTROS</div></div><div class="history-kpis"><div><span>OPERACOES ENCERRADAS</span><strong>0</strong></div><div><span>TONELADAS</span><strong>0 t</strong></div><div><span>FARDOS</span><strong>0</strong></div><div><span>EVENTOS REGISTRADOS</span><strong>0</strong></div></div><section class="panel empty-report"><div class="empty-state">Nenhum historico encontrado para esta data.<br><span class="muted">As operacoes aparecerao aqui depois de serem finalizadas e registradas.</span></div></section>`;};
const baseShowNotifications=showNotifications; showNotifications=()=>{baseShowNotifications();document.querySelectorAll('#notifications-popover .notification-item').forEach(item=>{const operation=operations.find(candidate=>item.textContent.includes(candidate.dt));if(operation&&!isActiveOperation(operation))item.remove();});};
function updateNotificationBadge(){const activeAlerts=operations.filter(operation=>isActiveOperation(operation)&&(operation.risk==='red'||operation.risk==='orange')).length;const badge=document.querySelector('.notification b');if(badge){badge.textContent=String(activeAlerts);badge.hidden=activeAlerts===0;}const notificationButton=document.querySelector('.notification');if(notificationButton)notificationButton.classList.toggle('has-alerts',activeAlerts>0);}
showNotifications=()=>{const activeAlerts=operations.filter(operation=>isActiveOperation(operation)&&(operation.risk==='red'||operation.risk==='orange'));let panel=document.querySelector('#notifications-popover');if(panel){panel.classList.toggle('open');return;}panel=document.createElement('section');panel.id='notifications-popover';panel.innerHTML=`<div class="notification-head"><strong>NOTIFICACOES</strong><button onclick="closeNotifications()">×</button></div>${activeAlerts.length?`<div class="notification-summary">${activeAlerts.length} alerta(s) exigem acompanhamento</div>${activeAlerts.map(operation=>`<button class="notification-item ${operation.risk==='red'?'critical':'warning'}" onclick="closeNotifications();openOperationDetail('${operation.dt}')"><span class="notification-icon">!</span><span><b>${operation.risk==='red'?'SLA PERDIDO':'SLA EM RISCO'}</b><small>${operation.dt} · ${operation.client}</small></span><i>→</i></button>`).join('')}`:'<div class="notification-empty">Nenhuma notificacao ativa.</div>'}<div class="notification-foot" onclick="closeNotifications();location.hash='tempo-real'">VER TEMPO REAL →</div>`;document.body.appendChild(panel);requestAnimationFrame(()=>panel.classList.add('open'));};
function updateDashboardMetrics(){const total=operations.length;const exited=operations.filter(operation=>operation.status==='SAIDA REALIZADA').length;const finished=operations.filter(operation=>operation.status.includes('FINALIZADO')||operation.status==='SAIDA REALIZADA').length;const active=operations.filter(operation=>operation.status.includes('EM ANDAMENTO')).length;const waiting=operations.filter(operation=>['AGUARDANDO','NO PATIO','NA DOCA','AGUARDANDO DOCA','AGUARDANDO SAIDA'].some(status=>operation.status.includes(status))).length;const tons=operations.reduce((sum,operation)=>sum+Number(operation.tons||operation.weight||0),0);const bales=operations.reduce((sum,operation)=>sum+Number(operation.bales||operation.fardos||0),0);const alerts=operations.filter(operation=>isActiveOperation(operation)&&(operation.risk==='red'||operation.risk==='orange')).length;const values=[total,finished,active,waiting,exited];document.querySelectorAll('.compact-kpis .kpi-value').forEach((node,index)=>{if(values[index]!==undefined)node.textContent=String(values[index]).padStart(2,'0');});const summaryValues=document.querySelectorAll('.summary-card .summary-value');if(summaryValues[0])summaryValues[0].innerHTML=`${tons} <small>t</small>`;if(summaryValues[1])summaryValues[1].textContent=String(alerts).padStart(2,'0');const summaryNotes=document.querySelectorAll('.summary-card .summary-note');if(summaryNotes[0])summaryNotes[0].textContent=`${bales.toLocaleString('pt-BR')} fardos`;if(summaryNotes[1])summaryNotes[1].textContent=alerts?'Acompanhar operacoes em excecao':'Nenhum alerta ativo';const movement=document.querySelector('.movement-content');if(movement)movement.innerHTML=`<strong>${total}</strong> veiculos registrados · <span>${active} em operacao</span> · <span>${finished} finalizados</span>`;}
function updateLiveLabels(){const period=currentPeriod();const dateLong=period.date;const dayLong=period.now.toLocaleDateString('pt-BR',{weekday:'long'}).toUpperCase();document.querySelectorAll('.panel-meta,.report-banner strong,.manager-filters .active-filter').forEach(node=>{node.textContent=node.textContent.replace(/26\/08\/2026|26 AGO 2026|26 DE AGOSTO DE 2026|QUARTA-FEIRA|Turno T2|TURNO T2/gi,match=>/turno/i.test(match)?`Turno ${period.turno}`:match.includes('/')?formatDate(period.now):match.includes('DE')?dateLong:match.includes('TURNO')?`TURNO ${period.turno}`:match==='QUARTA-FEIRA'?dayLong:dateLong);});}
