function switchProgramTab(type){document.querySelectorAll('.program-tab').forEach(tab=>tab.classList.toggle('active',tab.dataset.program===type)); const instruction=document.querySelector('#program-instruction'); if(instruction)instruction.textContent=`Cole abaixo as linhas copiadas da planilha de ${type.toLowerCase()}. O layout oficial sera aplicado quando definido.`; document.querySelector('#program-paste').value=''; document.querySelector('#paste-status').textContent='Nenhum dado recebido'; document.querySelector('#program-preview').innerHTML='<div class="empty-state">Nenhuma programacao carregada para esta data.<br><span class="text-link">Cole os dados acima para visualizar a previa.</span></div>';}
function toOperationDate(value){const clean=value?.trim();if(/^\d{2}\/\d{2}\/\d{4}$/.test(clean))return clean.split('/').reverse().join('-');if(/^\d{4}-\d{2}-\d{2}$/.test(clean))return clean;const monthNames={jan:1,fev:2,mar:3,abr:4,mai:5,jun:6,jul:7,ago:8,set:9,out:10,nov:11,dez:12};const shortDate=clean?.match(/^(\d{1,2})\s*\/\s*([a-zç]+)$/i);if(shortDate){const month=monthNames[shortDate[2].slice(0,3).toLowerCase()];if(month)return `${saoPauloNow().getFullYear()}-${String(month).padStart(2,'0')}-${String(shortDate[1]).padStart(2,'0')}`;}return saoPauloNow().toISOString().slice(0,10);}
async function importProgramming(rows){if(!authenticatedUser){toast('Faca login antes de importar');return;}const selectedType=document.querySelector('.program-tab.active')?.dataset.program||'CARREGAMENTO';const headerIndex=rows.findIndex(row=>/origem|data opera|dt sap/i.test(row[0]||'')||/dt sap/i.test(row[1]||''));const headers=headerIndex>=0?rows[headerIndex]:[];const dataRows=headerIndex>=0?rows.slice(headerIndex+1):rows;const isDischarge=/origem|dt entrada sap/i.test(headers.join(' '));const payload=dataRows.map(row=>isDischarge?({dt:row[1]?.trim(),operation_date:toOperationDate(row[2]),client:row[0]?.trim()||'Nao informado',carrier:row[6]?.trim()||'Nao informado',driver:row[7]?.trim()||'Nao informado',tons:Number((row[8]||'').replace(/\./g,'').replace(',','.'))||null,plate:row[9]?.trim()||'Nao informado',status:row[10]?.trim()?.includes('TRÂNSITO')?'AGUARDANDO':'AGUARDANDO',dock_number:row[12]?.trim()?.replace(/DOCA\s*/i,'')||null,history_problem:row[13]?.trim()||null,operation_type:'DESCARGA',risk:'green',tone:'blue',age:'current',sla:'02:00',elapsed:'00:00',next_action:'REGISTRAR CHEGADA'}):({dt:row[1]?.trim(),operation_date:toOperationDate(row[0]),otm_date:row[2]?.trim()?toOperationDate(row[2]):null,otm_time:row[3]?.trim()||null,tons:Number((row[4]||'').replace(/\./g,'').replace(',','.'))||null,history_problem:row[5]?.trim()||null,status:row[6]?.trim()?.includes('CARREGANDO')?'CARREGAMENTO EM ANDAMENTO':'AGUARDANDO',guide_call:row[7]?.trim()||null,delivery_info:row[8]?.trim()||null,load_type:row[9]?.trim()||null,dock_number:row[10]?.trim()?.replace(/DOCA\s*/i,'')||null,client:row[11]?.trim()||'Nao informado',uf:row[12]?.trim()||null,driver:row[13]?.trim()||'Nao informado',plate:row[14]?.trim()||'Nao informado',horse_plate:row[14]?.trim()||null,composition:row[15]?.trim()||null,carrier:row[16]?.trim()||'Nao informado',operation_type:selectedType,risk:'green',tone:'blue',age:'current',sla:'02:00',elapsed:'00:00',next_action:'REGISTRAR CHEGADA'})).filter(item=>item.dt);if(!payload.length){toast('Nao encontrei linhas validas para importar');return;}const result=await supabaseClient.from('operations').upsert(payload,{onConflict:'dt'});if(result.error){toast('Erro ao importar programacao para o servidor');return;}toast(`${payload.length} operacao(oes) importada(s) com sucesso`);await loadRemoteState();}
function previewProgramming(){const text=document.querySelector('#program-paste').value.trim(); const preview=document.querySelector('#program-preview'); if(!text){toast('Cole os dados da planilha antes de visualizar'); return;} const rows=text.split(/\r?\n/).filter(Boolean).map(row=>row.split('\t')); const columns=rows[0].map((_,index)=>`COLUNA ${index+1}`); preview.innerHTML=`<div class="panel-head"><span class="panel-title">PREVIA DA IMPORTACAO</span><span class="panel-meta">${rows.length} linha(s) · aguardando confirmacao</span></div><div class="table-wrap"><table class="operations"><thead><tr>${columns.map(column=>`<th>${column}</th>`).join('')}</tr></thead><tbody>${rows.slice(0,8).map(row=>`<tr>${columns.map((_,index)=>`<td>${row[index]||'<span class="muted">vazio</span>'}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div class="preview-confirm"><span class="muted">DT · data · placa · cliente · transportadora · motorista</span><button class="btn btn-primary" onclick="importProgramming(${JSON.stringify(rows).replace(/"/g,'&quot;')})">CONFIRMAR IMPORTACAO</button></div>`; document.querySelector('#paste-status').textContent=`${rows.length} linha(s) pronta(s) para revisao`;}
